function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (!/^[0-9]+$/.test(s)) return 's may contain only digits.';
  if (s[0] === '0') return 's cannot start with 0.';
  if (!Number.isInteger(k) || k < 1 || k > 1000000000) return 'k must be between 1 and 10^9.';
  return null;
}

