function numberOfArrays(s, k) {
  const MOD = 1e9 + 7;
  const n = s.length;
  const dp = new Array(n + 1).fill(0);
  dp[n] = 1;

  for (let start = n - 1; start >= 0; start--) {
    if (s[start] === '0') {
      continue;
    }
    let value = 0;
    for (let end = start; end < n; end++) {
      value = value * 10 + Number(s[end]);
      if (value > k) {
        break;
      }
      dp[start] = (dp[start] + dp[end + 1]) % MOD;
    }
  }
  return dp[0];
}

