function numberOfArrays(s, k) {
  // Forward over prefixes: ways[i] = splits of s.slice(0, i). Each piece is checked as a string.
  const MOD = 1000000007n;
  const limit = BigInt(k);
  const ways = [1n];
  for (let i = 1; i <= s.length; i++) {
    let total = 0n;
    for (let j = Math.max(0, i - 11); j < i; j++) {
      const piece = s.slice(j, i);
      if (piece[0] === '0') continue;
      if (BigInt(piece) > limit) continue;
      total += ways[j];
    }
    ways.push(total % MOD);
  }
  return Number(ways[s.length]);
}

