function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 10000 : 1 + Math.floor(rand() * 10);
  const zeroChance = large ? 0.1 : [0, 0.2, 0.4][Math.floor(rand() * 3)];
  const top = large ? 9 : [2, 5, 9][Math.floor(rand() * 3)];
  let s = String(1 + Math.floor(rand() * top));
  while (s.length < n) s += rand() < zeroChance ? '0' : String(1 + Math.floor(rand() * top));
  let k;
  if (large) k = rand() < 0.3 ? 1000000000 : 10000 + Math.floor(rand() * 999990001);
  else {
    const pick = Math.floor(rand() * 4);
    k = pick === 0 ? 1 + Math.floor(rand() * 30) : pick === 1 ? 1 + Math.floor(rand() * 1000) : pick === 2 ? [1, 10, 100, 1000, 1000000000][Math.floor(rand() * 5)] : 1 + Math.floor(rand() * 1000000000);
  }
  return [s, k];
}
